from modules.byte_program import *
import random
MASK=(1<<64)-1
def fp(b):
 h=0
 for x in b:h=(h*257+x+1)&MASK
 return len(b),h
random.seed(1)
for trial in range(7):
 b=b''.join(bytes([random.randrange(256)]) for _ in range(random.randrange(50)))
 n=literal(b); expr=n
 for step in range(20):
  typ=random.randrange(4)
  if typ==0:
   other=literal(bytes(random.randrange(256) for _ in range(random.randrange(5))))
   expr=concat(expr,other)
  elif typ==1:
   expr=repeat(expr,random.randrange(0,4))
  elif typ==2:
   if expr.size:
    s=random.randrange(expr.size+1); e=random.randrange(s,expr.size+1); expr=cut(expr,s,e)
  else:
   expr=concat(literal(bytes(range(random.randrange(4)))),expr)
 if expr.size>100000: continue
 m=materialize(expr,100000)
 if trial==6:
  print('expr size',expr.size,type(expr))
  def walk(n,d=0):
   print(' '*d,type(n).__name__,n.size,'fp',full_fp(n),'mat',materialize(n,100000), 'direct',fp(materialize(n,100000)))
   if isinstance(n,_Cat):
    for ch in n.parts: walk(ch,d+1)
   elif isinstance(n,_Rep): walk(n.part,d+1)
   elif isinstance(n,_Slice): walk(n.part,d+1); print(' '*d,'slice',n.start,n.end)
  walk(expr)
  print('full',full_fp(expr),'want',fp(m))
  break
